function portfolioPrintHtml(report){const rows=report.report_rows||[];const totalToCollect=rows.reduce((sum,row)=>sum+Math.max(0,Number(row.installment_amount??row.quincenal_amount??row.pago_quincenal??row.amount_due)||0),0);const denominations=[1000,500,200,100,50,20];const pages=[];for(let i=0;i<rows.length;i+=30)pages.push(rows.slice(i,i+30));if(!pages.length)pages.push([]);const renderRows=group=>group.map(x=>`<tr><td>${esc(x.folio||'—')}</td><td>${esc(x.policy_number||'—')}</td><td>${esc(x.patient_name||'—')}</td><td>${money(x.installment_amount??x.quincenal_amount??x.pago_quincenal??0)}</td><td class="blank">&nbsp;</td></tr>`).join('');return `<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Listado de recibos · Quincena</title><style>@page{size:A4 portrait;margin:5mm}*{box-sizing:border-box}html,body{margin:0;padding:0;color:#111;font-family:Arial,sans-serif}body{font-size:8px}.report-page{height:287mm;position:relative;page-break-after:always;break-after:page;overflow:hidden;padding:0}.report-page:last-child{page-break-after:auto;break-after:auto}h1{font-size:13px;text-align:center;margin:0 0 2px}h2{font-size:10px;text-align:center;margin:0 0 3px}p{margin:2px 0}.meta{font-size:8px;margin-bottom:3px}table{width:100%;border-collapse:collapse;table-layout:fixed;margin:0}th,td{border:.5px solid #555;padding:1px 3px;text-align:left;line-height:1;overflow-wrap:anywhere}th{font-size:7px;background:#eee}td{font-size:7px;height:4.5mm}th:nth-child(1),td:nth-child(1){width:12%}th:nth-child(2),td:nth-child(2){width:17%}th:nth-child(3),td:nth-child(3){width:37%}th:nth-child(4),td:nth-child(4){width:14%;text-align:right}th:nth-child(5),td:nth-child(5){width:20%}td.blank{height:4.5mm}.closing{position:absolute;left:0;right:0;bottom:0;border-top:.5px solid #888;padding-top:1.5mm;background:#fff}.closing h3{font-size:8px;margin:0 0 1mm}.due-total{font-size:8px;font-weight:bold;margin:0 0 1mm}.cash-table{width:70%;margin:0;font-size:6px}.cash-table th,.cash-table td{font-size:6px;text-align:center;padding:0 2px;height:3.3mm;line-height:1}.cash-table td.write{height:3.3mm}.cash-notes{font-size:6px;margin-top:1mm;display:flex;gap:5mm}.signature{font-size:6px;display:flex;justify-content:space-between;gap:10mm;margin-top:1.5mm}.signature span{border-top:.5px solid #555;padding-top:1mm;width:45%;text-align:center}.page-footer{font-size:6px;position:absolute;right:0;bottom:1mm}@media screen{body{padding:8px}.report-page{height:287mm;width:200mm;margin:0 auto 10px;border:1px solid #ddd;padding:0}}button{margin:4px}@media print{button{display:none!important}.report-page{width:100%;margin:0;border:0;padding:0}}</style></head><body><button onclick="window.print()">Imprimir</button>${pages.map((group,index)=>`<section class="report-page"><h1>DENTAL JG</h1><h2>Listado de recibos · Quincena ${esc(report.quincena_date)}</h2><p class="meta"><b>Gestor:</b> ${esc(report.manager_name)} · <b>Clientes:</b> ${rows.length} · Hoja ${index+1} de ${pages.length}</p><table><thead><tr><th>Folio</th><th>Número de póliza</th><th>Nombre del cliente</th><th>Pago quincenal</th><th>Pago recibido</th></tr></thead><tbody>${renderRows(group)}</tbody></table>${index===pages.length-1?`<section class="closing"><h3>CIERRE DE COBRANZA</h3><p class="due-total">SALDO TOTAL DE RECIBOS A COBRAR: ${money(totalToCollect)}</p><table class="cash-table"><thead><tr><th>Denominación</th><th>Cantidad</th><th>Importe</th></tr></thead><tbody>${denominations.map(value=>`<tr><td>${money(value)}</td><td class="write">&nbsp;</td><td class="write">&nbsp;</td></tr>`).join('')}<tr><td>Monedas (total)</td><td class="write">&nbsp;</td><td class="write">&nbsp;</td></tr><tr><th colspan="2">TOTAL EFECTIVO ENTREGADO</th><td class="write">&nbsp;</td></tr></tbody></table><div class="cash-notes"><span>Importe esperado: ________________</span><span>Diferencia: ________________</span></div><div class="signature"><span>Entrega del gestor</span><span>Recibido por</span></div></section>`:''}<span class="page-footer">Dental JG · ${index+1}/${pages.length}</span></section>`).join('')}</body></html>`} function previewPortfolioReport(report,existingWindow=null,doPrint=false){if(!report)return;if(doPrint){try{localStorage.setItem('dentaljg_last_printed_listing_v1',JSON.stringify({id:String(report.id||''),quincena_date:report.quincena_date,manager_id:report.manager_id,manager_name:report.manager_name,report_rows:report.report_rows||[],printed_at:new Date().toISOString()}))}catch(e){}}const full=portfolioPrintHtml(report);const printHtmlDocument=()=>{if(window.AndroidPrint&&typeof window.AndroidPrint.printReceipt==='function'){const parsed=new DOMParser().parseFromString(full,'text/html');const body=parsed.head.querySelector('style')?.outerHTML+parsed.body.innerHTML;window.AndroidPrint.printReceipt(body);return}const w=existingWindow||window.open('','_blank');if(!w){toast('El navegador bloqueó la ventana. Permite ventanas emergentes y vuelve a pulsar.');return}w.document.open();w.document.write(full);w.document.close();w.onload=()=>w.print()};if(doPrint){printHtmlDocument();return}let dlg=document.getElementById('portfolioPreviewDialog');if(!dlg){dlg=document.createElement('dialog');dlg.id='portfolioPreviewDialog';dlg.className='portfolio-preview-dialog';dlg.innerHTML='<div class="portfolio-preview-toolbar"><strong>Vista previa del listado</strong><div class="portfolio-preview-controls"><button type="button" id="portfolioZoomOut" aria-label="Alejar">−</button><span id="portfolioZoomLevel">100%</span><button type="button" id="portfolioZoomIn" aria-label="Acercar">+</button><button type="button" id="portfolioZoomReset">Ajustar</button><button type="button" id="portfolioPreviewPrint">Imprimir</button><button type="button" id="portfolioPreviewClose">Cerrar</button></div></div><iframe title="Vista previa del listado" class="portfolio-preview-frame"></iframe>';document.body.append(dlg);const frame=dlg.querySelector('iframe');let zoom=1;const applyZoom=()=>{try{const doc=frame.contentDocument;if(doc){doc.documentElement.style.zoom=String(zoom);doc.body.style.zoom=String(zoom)}dlg.querySelector('#portfolioZoomLevel').textContent=Math.round(zoom*100)+'%'}catch(e){}};dlg.querySelector('#portfolioZoomIn').onclick=()=>{zoom=Math.min(2.5,Math.round((zoom+.15)*100)/100);applyZoom()};dlg.querySelector('#portfolioZoomOut').onclick=()=>{zoom=Math.max(.35,Math.round((zoom-.15)*100)/100);applyZoom()};dlg.querySelector('#portfolioZoomReset').onclick=()=>{zoom=1;applyZoom()};dlg.querySelector('#portfolioPreviewClose').onclick=()=>dlg.close();dlg.querySelector('#portfolioPreviewPrint').onclick=()=>{if(window.AndroidPrint&&typeof window.AndroidPrint.printReceipt==='function'){printHtmlDocument();return}const frame=dlg.querySelector('iframe');if(frame?.contentWindow){frame.contentWindow.focus();frame.contentWindow.print()}else printHtmlDocument()};dlg._applyPortfolioZoom=applyZoom;dlg._setPortfolioContent=html=>{frame.srcdoc=html;frame.onload=()=>dlg._applyPortfolioZoom?.()};}dlg._setPortfolioContent(full);if(!dlg.open)dlg.showModal()}async function loadSavedReports(){const body=$('portfolioRows');if(!db){savedReports=[];if(body)body.innerHTML='<tr><td colspan="4" class="empty">La conexión con Supabase todavía no está lista. Actualiza el archivo en unos segundos.</td></tr>';return}try{const {data,error}=await db.from('collection_quincena_reports').select('*').order('created_at',{ascending:false});if(error)throw error;savedReports=Array.isArray(data)?data:[];renderHistoricalPortfolioRows();const legacyBody=$('savedReportRows');if(legacyBody)legacyBody.innerHTML='';}catch(e){console.error('Error al cargar collection_quincena_reports:',e);savedReports=[];if(body)body.innerHTML='<tr><td colspan="4" class="empty">No se pudo consultar el archivo histórico de Supabase. Revisa permisos RLS y la tabla collection_quincena_reports.</td></tr>';const legacyBody=$('savedReportRows');if(legacyBody)legacyBody.innerHTML=''}}
function updatePortfolioSummary(){const q=quincenaForNow();if($('nextPortfolioDate'))$('nextPortfolioDate').textContent=date(q);const id=$('receiptPortfolioManager')?.value||'';const manager=managers.find(m=>String(m.id)===String(id));const count=id?rowsForManager(id).length:0;if($('portfolioMsg')&&manager)$('portfolioMsg').textContent='Gestor: '+manager.full_name+' · '+count+' clientes en la cartera.';}
function showPrintHistory(){let receiptsPrinted=[],last=null;try{receiptsPrinted=JSON.parse(localStorage.getItem('dentaljg_printed_receipts_v1')||'[]');last=JSON.parse(localStorage.getItem('dentaljg_last_printed_listing_v1')||'null')}catch(e){}const lines=['HISTORIAL DE IMPRESIÓN (este dispositivo)','Recibos registrados como enviados a impresión: '+receiptsPrinted.length,last?'Último listado: '+date(last.quincena_date)+' · '+(last.manager_name||'Sin gestor')+' · '+(last.printed_at?new Date(last.printed_at).toLocaleString('es-MX'):'fecha de impresión no registrada'):'Todavía no hay un listado registrado como impreso.'];alert(lines.join('\n\n'));}
