function normalizeDateValue(value){return String(value||'').slice(0,10)}
function dateAtNoon(value){return new Date(String(value)+'T12:00:00')}
function scheduledInstallments(pt){const first=normalizeDateValue(pt.first_payment_date);const total=Math.max(1,Number(pt.installments||pt.payment_total||pt.total_payments||24));const mode=String(pt.payment_mode||pt.payment_frequency||'quincenal').toLowerCase();if(!first)return[];const out=[first];let cursor=first;for(let i=1;i<total;i++){if(mode.startsWith('mens')){const d=dateAtNoon(cursor),originalDay=dateAtNoon(first).getDate();d.setDate(1);d.setMonth(d.getMonth()+1);const last=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();d.setDate(Math.min(originalDay,last));cursor=normalizeDateValue(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`)}else cursor=nextQuincena(cursor,'quincenal');out.push(cursor)}return out}
