function extraReceiptEligiblePatients(){return patients.filter(pt=>{const managerId=String(pt.assigned_manager_id||portfolios.find(p=>portfolioPatients.some(a=>String(a.portfolio_id)===String(p.id)&&String(a.patient_id)===String(pt.id)))?.manager_id||'');return Number(pt.installment_amount||pt.quincenal_amount||0)>0&&Math.max(0,Number(pt.total||0)-Number(pt.paid||0))>0&&managers.some(m=>String(m.id)===managerId&&m.active!==false)}).sort((a,b)=>String(fullPatientName(a)).localeCompare(String(fullPatientName(b)),'es'))}
function extraReceiptNormalize(value){return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim()}
function extraReceiptSearchText(pt){return extraReceiptNormalize([pt.policy_number,pt.folio,fullPatientName(pt),pt.first_names,pt.surnames,pt.patient_name,pt.name,pt.address,pt.phone,pt.phone2,pt.clinic].join(' '))}
