async function generateAndPrintPortfolio(doPrint=false){const previewWindow=(doPrint&&!window.AndroidPrint?window.open('about:blank','_blank'):null);const managerId=$('reportManager')?.value||$('receiptPortfolioManager')?.value;if(!managerId){if(previewWindow)previewWindow.close();toast('Selecciona el gestor cuya cartera quieres imprimir.');return}const manager=managers.find(m=>String(m.id)===String(managerId));if(!manager){if(previewWindow)previewWindow.close();return}const dateValue=$('reportQuincena')?.value||quincenaForNow();let rows=rowsForManager(managerId);if(!rows.length){if(previewWindow)previewWindow.close();$('reportMsg').textContent='Este gestor no tiene pacientes asignados. Genera/actualiza las carteras y asigna una al gestor.';return}rows=rows.map(x=>({...x,folio:patients.find(p=>String(p.id)===String(x.patient_id))?.folio||x.folio||''}));const report={created_by:user.id,quincena_date:dateValue,manager_id:manager.id,manager_name:manager.full_name,report_rows:rows};try{const {data,error}=await db.from('collection_quincena_reports').upsert(report,{onConflict:'created_by,quincena_date,manager_id'}).select().single();if(error)throw error;await loadSavedReports();$('reportMsg').textContent=`Listado guardado: ${rows.length} clientes para ${manager.full_name}. Se conservará hasta generar la siguiente cartera.`;if(doPrint||previewWindow)previewPortfolioReport(data,previewWindow,doPrint);else previewPortfolioReport(data)}catch(e){if(previewWindow)previewWindow.close();console.error(e);$('reportMsg').textContent='No se pudo guardar el reporte. Ejecuta la migración SQL. Detalle: '+(e.message||'error')}}
function portfolioAssignmentsSignature(){const patientState=patients.map(pt=>[String(pt.id),String(pt.assigned_manager_id||""),(pt.clinic||"").trim()].join("|")).sort().join(";");const managerState=managers.map(m=>[String(m.id),m.active===false?"0":"1"].join("|")).sort().join(";");return patientState+"#"+managerState}
async function loadPortfolioData(skipAutoSync=false){try{const [m,p,a]=await Promise.all([db.from('collection_managers').select('id,created_by,full_name,phone,active,created_at,updated_at').order('full_name'),db.from('collection_portfolios').select('*').order('clinic_name'),db.from('collection_portfolio_patients').select('portfolio_id,patient_id,created_by')]);if(m.error)throw m.error;if(p.error)throw p.error;if(a.error)throw a.error;managers=m.data||[];portfolios=p.data||[];portfolioPatients=a.data||[];renderPortfolios();fillManagerSelectors();const rps=$('receiptPortfolioManager');if(rps){const keep=rps.value;rps.innerHTML='<option value="">Selecciona un gestor</option>'+managers.filter(m=>m.active!==false).map(m=>`<option value="${esc(m.id)}">${esc(m.full_name)}</option>`).join('');rps.value=managers.some(m=>String(m.id)===String(keep))?keep:(managers[0]?.id||'')}updatePortfolioSummary();await loadSavedReports();$('portfolioMsg').textContent='Carteras y gestores sincronizados.';if(!skipAutoSync&&!automaticPortfolioSyncInProgress&&patients.length){const signature=portfolioAssignmentsSignature();if(signature!==lastAutoPortfolioSignature){automaticPortfolioSyncInProgress=true;try{const syncOk=await generatePortfolios(true);if(syncOk)lastAutoPortfolioSignature=signature;}finally{automaticPortfolioSyncInProgress=false}}}return true}catch(e){console.error(e);$('portfolioMsg').textContent='Falta instalar la migración SQL actualizada de Cobranza. Detalle: '+(e.message||'error');renderHistoricalPortfolioRows();return false}}
async function createManager(e){e.preventDefault();const name=$('managerName').value.trim();if(!name)return;const btn=$('managerForm').querySelector('button[type="submit"]');btn.disabled=true;$('managerMsg').textContent='Guardando gestor…';try{const {data,error}=await db.from('collection_managers').insert({full_name:name,phone:$('managerPhone').value.trim(),created_by:user.id}).select('id,created_by,full_name,phone,active,created_at,updated_at').single();if(error)throw error;managers.push(data);managers.sort((a,b)=>a.full_name.localeCompare(b.full_name,'es'));$('managerForm').reset();renderPortfolios();$('managerMsg').textContent='Gestor registrado.';toast('Gestor registrado correctamente.')}catch(e){console.error(e);$('managerMsg').textContent=(e.code==='23505'?'Ese gestor ya está registrado.':'No se pudo registrar: '+(e.message||'revisa la migración SQL'))}finally{btn.disabled=false}}
async function generatePortfolios(automatic=false){if(!patients.length){$('portfolioMsg').textContent='No hay pacientes registrados para generar carteras.';if(!automatic)alert('Primero registra pacientes desde Registro de Clientes.');return false}const btn=$('generatePortfolios');if(btn&&!automatic){btn.disabled=true;btn.textContent='Generando carteras…'}$('portfolioMsg').textContent='Agrupando pacientes por clínica y gestor asignado…';try{const groups=new Map();let unassigned=0,createdGroups=0;for(const pt of patients){const managerId=String(pt.assigned_manager_id||'');if(!managerId){unassigned++;continue}const clinic=(pt.clinic||'').trim()||'Sin clínica';const key=managerId+'::'+clinic;if(!groups.has(key))groups.set(key,{managerId,clinic,patients:[]});groups.get(key).patients.push(pt)}const currentPatientIds=patients.map(pt=>String(pt.id)).filter(Boolean);if(currentPatientIds.length){const {error:deleteError}=await db.from('collection_portfolio_patients').delete().eq('created_by',user.id).in('patient_id',currentPatientIds);if(deleteError)throw deleteError}for(const group of groups.values()){const manager=managers.find(m=>String(m.id)===group.managerId);if(!manager||manager.active===false){unassigned+=group.patients.length;continue}const payload={created_by:user.id,clinic_name:group.clinic,name:`Cartera - ${group.clinic} - ${manager.full_name}`,manager_id:group.managerId,updated_at:new Date().toISOString()};const {data:portfolio,error}=await db.from('collection_portfolios').upsert(payload,{onConflict:'created_by,clinic_name,manager_id'}).select().single();if(error)throw error;createdGroups++;const assignments=group.patients.map(pt=>({created_by:user.id,portfolio_id:portfolio.id,patient_id:pt.id}));if(assignments.length){const {error:ae}=await db.from('collection_portfolio_patients').upsert(assignments,{onConflict:'portfolio_id,patient_id',ignoreDuplicates:true});if(ae)throw ae}}await loadPortfolioData(true);lastAutoPortfolioSignature=portfolioAssignmentsSignature();if(createdGroups){$('portfolioMsg').textContent=`Carteras creadas/actualizadas automáticamente: ${createdGroups} grupo(s) por clínica y gestor. ${unassigned?unassigned+' paciente(s) omitidos por falta de gestor activo/asignado. ':''}Se usa el gestor definido en Registro de clientes; ya no hay asignación manual.`;if(!automatic)toast('Carteras actualizadas por gestor y clínica.')}else{$('portfolioMsg').textContent='No hay carteras para generar: revisa que cada cliente tenga un gestor activo asignado en Registro de clientes.'}return true}catch(e){console.error(e);$('portfolioMsg').textContent='No se pudieron generar las carteras automáticamente. Revisa permisos y migración SQL. Detalle: '+(e.message||'error');return false}finally{if(btn&&!automatic){btn.disabled=false;btn.textContent='Generar / actualizar carteras'}}}
function archiveSearchNorm(value){return String(value??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('es-MX').trim()}function renderArchive(){const q=archiveSearchNorm($('archiveSearch')?.value||'');const rows=archivedPatients.filter(a=>{const hay=archiveSearchNorm([a.patient_name,a.first_names,a.surnames,a.holder_name,a.clinic,a.original_patient_id,a.policy_number,a.folio,a.address,a.phone,a.phone2,a.archive_reason].join(' '));return !q||q.split(/\s+/).every(term=>hay.includes(term))});$('archiveRows').innerHTML=rows.length?rows.map(a=>`<tr><td><b>${esc(a.patient_name||'Sin nombre')}</b><div class="archive-detail">${esc(a.original_patient_id)}</div></td><td>${esc(a.clinic||'—')}</td><td>${date(a.liquidated_at)}</td><td>${date(a.archived_at)}</td><td>${esc(a.archive_reason==='MANUAL'?'Manual':'Automático · 3 años')}</td><td><span class="archive-status">${a.restored_at?'Restaurado':'Archivado'}</span></td><td class="archive-actions">${a.restored_at?'<span>Ya restaurado</span>':`<button class="restore-btn" data-restore-archive="${a.id}">Restaurar</button>`}<button class="rowbtn ghost" data-view-archive="${a.id}">Ver expediente</button> ${isAdmin?`<button class="danger-btn" data-delete-archive="${a.id}">Eliminar archivo</button>`:''}</td></tr>`).join(''):'<tr><td colspan="7" class="empty">No hay expedientes que coincidan con la búsqueda.</td></tr>';document.querySelectorAll('[data-restore-archive]').forEach(b=>b.onclick=()=>restoreArchivedPatient(b.dataset.restoreArchive));document.querySelectorAll('[data-view-archive]').forEach(b=>b.onclick=()=>viewArchivedPatient(b.dataset.viewArchive));document.querySelectorAll('[data-delete-archive]').forEach(b=>b.onclick=()=>deleteArchivedPatient(b.dataset.deleteArchive));const aq=archiveSearchNorm($('activeArchiveSearch')?.value||'');const active=patients.filter(p=>{const hay=archiveSearchNorm([p.name,p.first_names,p.surnames,p.holder_name,p.phone,p.phone2,p.clinic,p.policy_number,p.folio,p.address,p.id].join(' '));return !aq||aq.split(/\s+/).every(term=>hay.includes(term))});$('activeArchiveRows').innerHTML=active.length?active.map(p=>{const total=Number(p.total)||0,paid=Number(p.paid)||0;return `<tr><td><b>${esc(p.name||'Sin nombre')}</b><div class="archive-detail">Folio: ${esc(p.folio||'—')} · Titular: ${esc(p.holder_name||p.name||'—')} · ${esc(p.phone||'Sin teléfono')}</div></td><td>${esc(p.clinic||'—')}<div class="archive-detail">${esc(p.payment_mode||'quincenal')} · Pago: ${money(p.installment_amount||0)} · Primer pago: ${date(p.first_payment_date)}</div></td><td>${money(total)}</td><td>${money(paid)}</td><td>${money(Math.max(0,total-paid))}</td><td><button class="rowbtn ghost" data-edit-active-patient="${p.id}">Editar</button> <button class="danger-btn" data-delete-active-patient="${p.id}">Eliminar cliente y pagos</button></td></tr>`}).join(''):'<tr><td colspan="6" class="empty">No hay clientes activos que coincidan.</td></tr>';document.querySelectorAll('[data-edit-active-patient]').forEach(b=>b.onclick=()=>editActivePatient(b.dataset.editActivePatient));document.querySelectorAll('[data-delete-active-patient]').forEach(b=>b.onclick=()=>deleteActivePatient(b.dataset.deleteActivePatient))}
async function deleteArchivedPatient(id){if(!isAdmin){toast('Solo Administración puede eliminar expedientes archivados.');return}const a=archivedPatients.find(x=>String(x.id)===String(id));if(!a)return;const name=a.patient_name||'este expediente';if(!confirm('¿Eliminar definitivamente el expediente archivado de '+name+'?\n\nSe eliminará únicamente este registro histórico. No se borrarán pagos de otros clientes ni se tocará el registro activo. Esta acción no se puede deshacer.'))return;try{const {error}=await db.rpc('delete_archived_patient',{p_archive_id:id});if(error)throw error;archivedPatients=archivedPatients.filter(x=>String(x.id)!==String(id));renderArchive();$('archiveAccessMsg').textContent='Archivo actualizado: '+archivedPatients.length+' expediente(s) histórico(s).';toast('Expediente archivado eliminado.')}catch(e){console.error(e);alert('No se pudo eliminar el expediente archivado. Detalle: '+(e.message||'revisa la política RLS DELETE de patient_account_archive.'))}}function renderActivePatients(){if(!$('activeArchiveRows'))return;const q=($('activeArchiveSearch')?.value||'').trim().toLocaleLowerCase('es-MX');const active=patients.filter(p=>[p.name,p.phone,p.clinic,p.policy_number].join(' ').toLocaleLowerCase('es-MX').includes(q));$('activeArchiveRows').innerHTML=active.length?active.map(p=>{const total=Number(p.total)||0,paid=Number(p.paid)||0;return `<tr><td><b>${esc(p.name||'Sin nombre')}</b><div class="archive-detail">Folio: ${esc(p.folio||'—')} · Titular: ${esc(p.holder_name||p.name||'—')} · ${esc(p.phone||'Sin teléfono')}</div></td><td>${esc(p.clinic||'—')}<div class="archive-detail">${esc(p.payment_mode||'quincenal')} · Pago: ${money(p.installment_amount||0)} · Primer pago: ${date(p.first_payment_date)}</div></td><td>${money(total)}</td><td>${money(paid)}</td><td>${money(Math.max(0,total-paid))}</td><td><button class="rowbtn ghost" data-edit-active-patient="${p.id}">Editar</button> <button class="danger-btn" data-delete-active-patient="${p.id}">Eliminar cliente y pagos</button></td></tr>`}).join(''):'<tr><td colspan="6" class="empty">No hay clientes activos que coincidan.</td></tr>';document.querySelectorAll('[data-edit-active-patient]').forEach(b=>b.onclick=()=>editActivePatient(b.dataset.editActivePatient));document.querySelectorAll('[data-delete-active-patient]').forEach(b=>b.onclick=()=>deleteActivePatient(b.dataset.deleteActivePatient))}
async function loadArchive(){if(!$('archiveRows'))return;renderActivePatients();if(!isAdmin){$('archiveAccessMsg').textContent='El archivo histórico requiere rol admin. Los clientes activos sí pueden editarse o eliminarse desde esta pantalla.';$('archiveRows').innerHTML='<tr><td colspan="7" class="empty">Archivo histórico disponible solo para administración.</td></tr>';return}$('archiveAccessMsg').textContent='Cargando archivo histórico…';try{const {data,error}=await db.from('patient_account_archive').select('*').order('archived_at',{ascending:false});if(error)throw error;archivedPatients=data||[];$('archiveAccessMsg').textContent=`Archivo actualizado: ${archivedPatients.length} expediente(s) histórico(s).`;renderArchive()}catch(e){console.error(e);$('archiveAccessMsg').textContent='No se pudo leer el archivo. Ejecuta el SQL de liquidación y archivo actualizado en Supabase. Detalle: '+(e.message||'error');$('archiveRows').innerHTML='<tr><td colspan="7" class="empty">No se pudo cargar el archivo.</td></tr>'}}
async function archiveActivePatient(id){if(!isAdmin){toast('Solo un administrador puede archivar clientes.');return}const p=patientFor(id);if(!p)return;const balance=Math.max(0,Number(p.total||0)-Number(p.paid||0));const ok=confirm(`¿Archivar y retirar a ${p.name||'este cliente'} de los registros activos?\n\nSe guardarán el expediente, pagos, recibos y asignaciones en el archivo histórico.\nSaldo actual: ${money(balance)}.\n\nPodrás restaurarlo después desde Archivo de clientes.`);if(!ok)return;try{const {data,error}=await db.rpc('archive_patient_account',{p_patient_id:id});if(error)throw error;toast('Cliente archivado y retirado de los registros activos.');await load(true);await loadPortfolioData();await loadArchive()}catch(e){console.error(e);alert('No se pudo archivar el cliente. No se hicieron cambios si la operación falló. Detalle: '+(e.message||'revisa permisos y SQL'))}}
async function editActivePatient(id){if(!canManageClients){toast('Tu cuenta no tiene permiso para editar clientes.');return}const p=patientFor(id);if(!p)return;const name=(prompt('Nombre(s) y apellidos del paciente:',p.name||'')||'').trim();if(!name)return;const holder=(prompt('Nombre(s) del titular:',p.holder_name||p.name||'')||'').trim();if(!holder)return;const phone=(prompt('Teléfono:',p.phone||'')||'').trim();const address=(prompt('Dirección:',p.address||'')||'').trim();const clinic=(prompt('Clínica:',p.clinic||'')||'').trim();const policy=(prompt('Póliza:',p.policy_number||'')||'').trim();const modeRaw=(prompt('Modo de pago (quincenal o mensual):',p.payment_mode||'quincenal')||'').trim().toLowerCase();if(!['quincenal','mensual'].includes(modeRaw)){alert('El modo de pago debe ser quincenal o mensual.');return}const tabRaw=prompt('Tabulador ($):',String(p.tabulator??0));if(tabRaw===null)return;const tabulator=Number(tabRaw);const amountRaw=prompt(modeRaw==='mensual'?'Cantidad mensual ($):':'Cantidad quincenal ($):',String(p.installment_amount??0));if(amountRaw===null)return;const installment_amount=Number(amountRaw);const countRaw=prompt(modeRaw==='mensual'?'Número de mensualidades:':'Número de quincenas:',String(p.installments??0));if(countRaw===null)return;const installments=parseInt(countRaw,10);const totalRaw=prompt('Monto total de la póliza ($):',String(p.total??0));if(totalRaw===null)return;const total=Number(totalRaw);const firstDate=prompt('Fecha del primer pago (AAAA-MM-DD):',p.first_payment_date||'');if(firstDate===null)return;if(!holder||!Number.isFinite(tabulator)||tabulator<0||!Number.isFinite(installment_amount)||installment_amount<=0||!Number.isInteger(installments)||installments<1||!Number.isFinite(total)||total<=0||!/^\d{4}-\d{2}-\d{2}$/.test(firstDate)){alert('Revisa los importes, el número de pagos y la fecha del primer pago.');return}try{const {error}=await db.from('patients').update({name,holder_name:holder,first_names:name.split(' ')[0]||'',surnames:name.split(' ').slice(1).join(' '),phone,address,clinic,policy_number:policy,payment_mode:modeRaw,tabulator,installment_amount,installments,total,first_payment_date:firstDate,updated_at:new Date().toISOString()}).eq('id',id);if(error)throw error;toast('Datos del cliente y condiciones de pago actualizados.');await load(true);await loadArchive()}catch(e){console.error(e);alert('No se pudo editar el cliente: '+(e.message||'revisa que se haya ejecutado la migración SQL y los permisos.'))}}async function deleteActivePatient(id){if(!canManageClients){toast('Tu cuenta no tiene permiso para eliminar clientes.');return}const p=patientFor(id);if(!p)return;const count=payments.filter(x=>String(x.patient_id||'')===String(id)).length;if(!confirm(`¿Eliminar definitivamente a ${p.name||'este cliente'} y sus ${count} pago(s)?\n\nSe eliminarán también sus recibos relacionados y asignaciones de cartera. Esta acción no se puede deshacer.`))return;try{const {error}=await db.rpc('delete_patient_permanently',{p_patient_id:id});if(error)throw error;toast('Cliente y pagos eliminados.');await load(true);await loadPortfolioData();await loadArchive()}catch(e){console.error(e);alert('No se pudo eliminar: '+(e.message||'ejecuta la migración DENTAL_JG_10_8_11_CORRECCIONES.sql y revisa permisos.'))}}
async function restoreArchivedPatient(id){if(!isAdmin)return;const a=archivedPatients.find(x=>String(x.id)===String(id));if(!a)return;const ok=confirm(`¿Restaurar a ${a.patient_name||'este cliente'}?\n\nSe restaurarán sus datos, pagos, recibos y asignaciones que aún puedan recuperarse. Se volverá a mostrar en los registros activos.`);if(!ok)return;try{const {data,error}=await db.rpc('restore_patient_account',{p_archive_id:id});if(error)throw error;toast('Cliente restaurado correctamente.');await load(true);await loadPortfolioData();await loadArchive()}catch(e){console.error(e);alert('No se pudo restaurar el expediente. No se marcará como restaurado si la operación falló. Detalle: '+(e.message||'revisa permisos y SQL'))}}
function viewArchivedPatient(id){const a=archivedPatients.find(x=>String(x.id)===String(id));if(!a)return;const d=a.archive_data||{},p=d.patient||{};const payments=Array.isArray(d.payments)?d.payments:[],receipts=Array.isArray(d.receipts)?d.receipts:[];const paymentHtml=payments.length?payments.map(x=>`<tr><td>${date(x.paid_at||x.created_at)}</td><td>${esc(x.concept||'Abono')}</td><td>${money(x.amount)}</td><td>${esc(x.reference||'—')}</td></tr>`).join(''):'<tr><td colspan="4">Sin pagos archivados</td></tr>';const receiptHtml=receipts.length?receipts.map(x=>`<tr><td>${esc(x.folio||'—')}</td><td>${date(x.created_at)}</td><td>${money(x.payment_amount)}</td><td>${esc(x.concept||'—')}</td></tr>`).join(''):'<tr><td colspan="4">Sin recibos archivados</td></tr>';const w=window.open('','_blank','width=900,height=700');if(!w){alert('El navegador bloqueó la ventana. Permite ventanas emergentes para consultar el expediente.');return}w.document.write(`<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Expediente archivado</title><style>body{font:15px Arial,sans-serif;padding:24px;color:#182230}h1,h2{color:#1769c2}table{width:100%;border-collapse:collapse;margin:12px 0 24px}th,td{text-align:left;padding:8px;border-bottom:1px solid #ddd}small{color:#667085}</style><h1>Expediente archivado · DENTAL JG</h1><h2>${esc(p.name||a.patient_name)}</h2><p><b>Clínica:</b> ${esc(p.clinic||a.clinic||'—')} &nbsp; <b>Teléfono:</b> ${esc(p.phone||'—')}</p><p><b>Total:</b> ${money(p.total)} &nbsp; <b>Pagado:</b> ${money(p.paid)} &nbsp; <b>Saldo:</b> ${money(Math.max(0,Number(p.total||0)-Number(p.paid||0)))}</p><p><b>Liquidación:</b> ${date(a.liquidated_at)} &nbsp; <b>Archivado:</b> ${date(a.archived_at)}</p><h2>Pagos (${payments.length})</h2><table><thead><tr><th>Fecha</th><th>Concepto</th><th>Importe</th><th>Referencia</th></tr></thead><tbody>${paymentHtml}</tbody></table><h2>Recibos (${receipts.length})</h2><table><thead><tr><th>Folio</th><th>Fecha</th><th>Importe</th><th>Concepto</th></tr></thead><tbody>${receiptHtml}</tbody></table><button onclick="print()">Imprimir expediente</button></html>`);w.document.close()}
async function loadSettings(){let {data,error}=await db.from('collection_receipt_settings').select('*').eq('user_id',user.id).maybeSingle();if(error)throw error;if(!data){let ins=await db.from('collection_receipt_settings').insert({user_id:user.id}).select().single();if(ins.error)throw ins.error;data=ins.data}settings=data;$('receiptTitle').value=data.receipt_title||'RECIBO DE COBRANZA';$('folioPrefix').value=data.folio_prefix||'JG-';$('nextFolio').value=data.next_folio||1;$('folioDigits').value=String(data.folio_digits||6);$('tabulatorDefault').value=data.tabulator_default||0;$('receiptFooter').value=data.receipt_footer||'Gracias por su pago.'}async function loadClinics(){if(!$('clinicRows'))return;try{const {data,error}=await db.from('clinics').select('*').order('name',{ascending:true});if(error)throw error;clinics=data||[];clinicTableAvailable=true;renderClinics()}catch(e){console.error('No se pudo cargar el catálogo de clínicas',e);clinicTableAvailable=false;$('clinicRows').innerHTML='<tr><td colspan="4" class="empty">No se pudo consultar public.clinics. Revisa la conexión y los permisos de Supabase.</td></tr>';$('clinicMsg').textContent='No se pudo cargar el catálogo compartido.'}}
function renderClinics(){if(!$('clinicRows'))return;const names=[...new Set(clinics.map(c=>String(c.name||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'es-MX'));const legacyNames=[...new Set(patients.map(p=>String(p.clinic||'').trim()).filter(Boolean))].filter(n=>!names.some(x=>x.toLocaleLowerCase('es-MX')===n.toLocaleLowerCase('es-MX')));$('clinicRows').innerHTML=names.length?names.map(name=>{const c=clinics.find(x=>String(x.name||'').trim().toLocaleLowerCase('es-MX')===name.toLocaleLowerCase('es-MX'));const count=patients.filter(p=>String(p.clinic||'').trim().toLocaleLowerCase('es-MX')===name.toLocaleLowerCase('es-MX')).length;const actions=canManageClients?(c?`<button class="rowbtn ghost" data-edit-clinic="${esc(c.id)}">Editar</button> <button class="danger-btn" data-delete-clinic="${esc(c.id)}">Eliminar</button>`:`<button class="rowbtn ghost" data-register-clinic="${esc(name)}">Agregar al catálogo</button>`):'<span>Solo consulta</span>';return `<tr><td><b>${esc(name)}</b></td><td>${count}</td><td>${c?'Catálogo compartido':'Nombre antiguo de paciente'}</td><td>${actions}</td></tr>`}).join(''):'<tr><td colspan="4" class="empty">No hay clínicas registradas.</td></tr>';if(legacyNames.length)$('clinicRows').innerHTML+=legacyNames.map(name=>`<tr><td>${esc(name)}</td><td>${patients.filter(p=>String(p.clinic||'').trim().toLocaleLowerCase('es-MX')===name.toLocaleLowerCase('es-MX')).length}</td><td>Asignación en expedientes</td><td><button class="danger-btn" data-clear-legacy-clinic="${esc(name)}">Quitar asignación</button></td></tr>`).join('');document.querySelectorAll('[data-clear-legacy-clinic]').forEach(b=>b.onclick=()=>clearLegacyClinic(b.dataset.clearLegacyClinic));document.querySelectorAll('[data-edit-clinic]').forEach(b=>b.onclick=()=>editClinic(b.dataset.editClinic));document.querySelectorAll('[data-delete-clinic]').forEach(b=>b.onclick=()=>deleteClinic(b.dataset.deleteClinic));document.querySelectorAll('[data-register-clinic]').forEach(b=>b.onclick=()=>registerLegacyClinic(b.dataset.registerClinic));if($('clinicForm'))$('clinicForm').querySelector('button[type="submit"]').disabled=!canManageClients;if($('clinicMsg')&&!canManageClients)$('clinicMsg').textContent='Tu cuenta puede consultar clínicas, pero no tiene permiso para editarlas o eliminarlas.'}
async function clearLegacyClinic(name){if(!canManageClients){toast('Tu cuenta no tiene permiso para modificar clientes.');return}const count=patients.filter(p=>String(p.clinic||'').trim().toLocaleLowerCase('es-MX')===String(name||'').trim().toLocaleLowerCase('es-MX')).length;if(!count)return;if(!confirm('¿Quitar la clínica «'+name+'» de '+count+' expediente(s)? Los clientes, pagos y recibos se conservarán; solo se limpiará el campo clínica.'))return;try{const {error}=await db.from('patients').update({clinic:''}).eq('clinic',name);if(error)throw error;await load(true);await loadClinics();await loadPortfolioData();toast('Asignación de clínica eliminada; los expedientes se conservaron.')}catch(e){console.error(e);toast('No se pudo quitar la clínica: '+(e.message||'revisa permisos de Supabase'))}}
async function registerLegacyClinic(name){if(!canManageClients){toast('Tu cuenta no tiene permiso para administrar clínicas.');return}const clean=String(name||'').trim();if(!clean)return;const {data,error}=await db.from('clinics').insert({name:clean,active:true}).select('*').single();if(error){console.error(error);toast('No se pudo agregar al catálogo: '+(error.message||'revisa permisos'));return}clinics.push(data);renderClinics();toast('Clínica agregada al catálogo compartido.')}
async function addClinic(e){e.preventDefault();if(!canManageClients){toast('Tu cuenta no tiene permiso para administrar clínicas.');return}const name=$('clinicName').value.trim();if(!name)return;if([...clinics.map(c=>c.name),...patients.map(p=>p.clinic)].some(n=>String(n||'').trim().toLocaleLowerCase('es-MX')===name.toLocaleLowerCase('es-MX'))){toast('Esa clínica ya existe o ya está asignada a pacientes.');return}const btn=$('saveClinic');btn.disabled=true;try{const {data,error}=await db.from('clinics').insert({name,active:true}).select('*').single();if(error)throw error;clinics.push(data);$('clinicName').value='';$('clinicMsg').textContent='Clínica agregada al catálogo compartido.';renderClinics();toast('Clínica agregada.')}catch(e){console.error(e);toast('No se pudo guardar la clínica: '+(e.message||'revisa permisos en Supabase'))}finally{btn.disabled=false}}
async function editClinic(id){if(!canManageClients){toast('Tu cuenta no tiene permiso para editar clínicas.');return}const c=clinics.find(x=>String(x.id)===String(id));if(!c)return;const next=(prompt('Escribe el nuevo nombre de la clínica:',c.name)||'').trim();if(!next||next===c.name)return;if([...clinics].some(x=>String(x.id)!==String(id)&&String(x.name||'').trim().toLocaleLowerCase('es-MX')===next.toLocaleLowerCase('es-MX'))){toast('Ya existe una clínica con ese nombre.');return}const old=c.name;try{const {error}=await db.from('clinics').update({name:next}).eq('id',id);if(error)throw error;const {error:patientError}=await db.from('patients').update({clinic:next}).eq('clinic',old);if(patientError){console.error(patientError);toast('Se cambió el catálogo, pero no se pudieron actualizar todos los pacientes. Revisa permisos de patients.')}else toast('Clínica y asignaciones actualizadas.');await load(true);await loadClinics();await loadPortfolioData()}catch(e){console.error(e);toast('No se pudo modificar la clínica: '+(e.message||'revisa permisos en Supabase'))}}
async function deleteClinic(id){if(!canManageClients){toast('Tu cuenta no tiene permiso para eliminar clínicas.');return}const c=clinics.find(x=>String(x.id)===String(id));if(!c)return;const count=patients.filter(p=>String(p.clinic||'').trim().toLocaleLowerCase('es-MX')===String(c.name||'').trim().toLocaleLowerCase('es-MX')).length;const detail=count?`Hay ${count} paciente(s) asignado(s). Se conservarán sus expedientes y pagos, pero quedarán sin clínica.`:'No hay pacientes asignados.';if(!confirm(`¿Eliminar la clínica “${c.name}”?\n\n${detail}\nLos reportes históricos de carteras no se borrarán.`))return;try{if(count){const {error}=await db.from('patients').update({clinic:''}).eq('clinic',c.name);if(error)throw new Error('No se pudieron desasignar los pacientes: '+error.message)}const {error}=await db.from('clinics').delete().eq('id',id);if(error)throw error;await load(true);await loadClinics();await loadPortfolioData();toast('Clínica eliminada. Los expedientes, pagos y reportes históricos se conservaron.')}catch(e){console.error(e);toast('No se pudo eliminar la clínica: '+(e.message||'revisa permisos en Supabase'))}}
async function load(silent=false){try{const [p,a]=await Promise.all([db.from('patients').select('*').order('name'),db.from('payments').select('*').order('paid_at',{ascending:false})]);if(p.error)throw p.error;if(a.error)throw a.error;patients=p.data||[];payments=a.data||[];try{const r=await db.from('collection_receipts').select('*').order('created_at',{ascending:false});if(r.error)throw r.error;receipts=r.data||[]}catch(re){console.error(re);receipts=[];if(!silent)toast('Pacientes y pagos conectados; para recibos instala el SQL de Cobranza.')}render();connection(true,'Conectado · datos actualizados');if(!silent)toast('Datos actualizados');}catch(e){console.error(e);connection(false,'Error al consultar datos');if(!silent)toast('No se pudieron leer pacientes y pagos: '+(e.message||'revisa la conexión y permisos'))}}
